INSERT INTO grammar_points
  (id, language_id, slug, title, pattern, level_id, category, register, meaning_short, meaning_long, nuance, status, published, sort_index) VALUES
  ('gp-nashi-niwa', 'lang-ja', 'nashi-ni-wa', '〜なしには', 'Noun + なしには', 'lvl-ja-n1', 'expression', 'formal', 'Without it, not possible.', '彼の協力なしには成功しなかっただろう.', 'The second half must be negative. It names a precondition by ruling out the alternative, which is the same move Japanese makes for obligation.', 'in-review', true, 400),
  ('gp-tari-tomo', 'lang-ja', 'taritomo', '〜たりとも', 'Number + たりとも', 'lvl-ja-n1', 'expression', 'formal', 'Not even one.', '一日たりとも忘れたことはない.', 'Takes 一 and a counter, and demands a negative. A classical concessive kept alive almost entirely in this shape.', 'in-review', true, 401),
  ('gp-to-ie-domo', 'lang-ja', 'to-iedomo', '〜といえども', 'Noun / Plain form + といえども', 'lvl-ja-n1', 'conjunction', 'formal', 'Even though it be.', '専門家といえども、間違うことはある.', 'いえども is the classical concessive of 言う. It concedes a strong case and then denies that it settles anything.', 'in-review', true, 402),
  ('gp-to-wa', 'lang-ja', 'towa', '〜とは', 'Plain form + とは', 'lvl-ja-n1', 'particle', 'formal', 'To think that — surprise or indignation.', 'まさか彼が来るとは.', 'Often left unfinished, the 思わなかった simply dropped. The sentence trails off precisely because the speaker has no words for it.', 'in-review', true, 403),
  ('gp-mono-wo', 'lang-ja', 'mono-wo', '〜ものを', 'Plain form + ものを', 'lvl-ja-n1', 'conjunction', 'formal', 'If only — but you didn''t.', '言ってくれればよかったものを.', 'Regret about a road not taken, aimed at someone. It usually ends the sentence, the reproach left hanging.', 'in-review', true, 404),
  ('gp-beku', 'lang-ja', 'beku', '〜べく', 'Plain present + べく', 'lvl-ja-n1', 'conjunction', 'formal', 'In order to.', '真相を明らかにすべく、調査が始まった.', 'The classical adverbial of べし. Written only. べくもない is a separate survival meaning "there is no way to".', 'in-review', true, 405),
  ('gp-bekarazu', 'lang-ja', 'bekarazu', '〜べからず', 'Plain present + べからず', 'lvl-ja-n1', 'expression', 'formal', 'Must not — on signs.', '立入るべからず.', 'The classical negative of べし, now almost confined to notices and set phrases. It sounds archaic on purpose.', 'in-review', true, 406),
  ('gp-nagara-ni', 'lang-ja', 'nagara-ni', '〜ながらに', 'Noun / Verb stem + ながらに', 'lvl-ja-n1', 'expression', 'formal', 'While in that state, as one is.', '涙ながらに語った. 生まれながらに.', 'A frozen classical ながら meaning "as it is", not "while doing". It survives in a handful of set phrases and nowhere else.', 'in-review', true, 407),
  ('gp-yaina-ya', 'lang-ja', 'ya-ina-ya', '〜や否や', 'Plain present + や否や', 'lvl-ja-n1', 'conjunction', 'formal', 'The moment that.', '席に着くや否や、話し始めた.', 'Immediate and unplanned. Because it reports what happened, it cannot take a request or an intention.', 'in-review', true, 408),
  ('gp-ga-hayai-ka', 'lang-ja', 'ga-hayai-ka', '〜が早いか', 'Plain present + が早いか', 'lvl-ja-n1', 'conjunction', 'formal', 'No sooner than.', 'ベルが鳴るが早いか、飛び出した.', 'Even tighter than や否や, and it implies the second action was already poised. Narrative register.', 'in-review', true, 409),
  ('gp-nari', 'lang-ja', 'nari-immediately', '〜なり', 'Plain present + なり', 'lvl-ja-n1', 'conjunction', 'formal', 'As soon as — and unexpectedly.', '部屋に入るなり、泣き出した.', 'The second action must surprise. Someone doing the expected thing on arrival does not take なり.', 'in-review', true, 410),
  ('gp-sokonau', 'lang-ja', 'sokoneru', '〜そこねる', 'Verb stem + そこねる', 'lvl-ja-n1', 'auxiliary', 'casual', 'Fail to, miss doing.', '電車に乗りそこねた.', 'A missed chance, not an inability. 乗れなかった could mean the train was full; 乗りそこねた means you were too slow.', 'in-review', true, 411),
  ('gp-kaneru', 'lang-ja', 'kaneru', '〜かねる', 'Verb stem + かねる', 'lvl-ja-n1', 'auxiliary', 'formal', 'Cannot bring oneself to.', 'お答えしかねます.', 'A refusal dressed as an inability, which is exactly why service Japanese reaches for it. Its negative かねない warns instead.', 'in-review', true, 412),
  ('gp-madeda', 'lang-ja', 'made-da', '〜までだ', 'Plain present + までだ', 'lvl-ja-n1', 'expression', 'formal', 'I''ll simply do it, that''s all.', 'だめなら、やり直すまでだ.', 'Resolve, stated flatly. It presents a fallback as costing nothing, which is where its stoicism comes from.', 'in-review', true, 413),
  ('gp-made-mo-nai', 'lang-ja', 'made-mo-nai', '〜までもない', 'Plain present + までもない', 'lvl-ja-n1', 'expression', 'formal', 'No need to go so far as to.', '言うまでもない.', 'It dismisses an action as unnecessary rather than impossible — the thing is so obvious that doing it would be excessive.', 'in-review', true, 414),
  ('gp-ni-taenai', 'lang-ja', 'ni-taenai', '〜に堪えない', 'Noun + に堪えない', 'lvl-ja-n1', 'expression', 'formal', 'Unbearable to, or deeply felt.', '見るに堪えない. 感謝に堪えません.', 'Two opposite tones from one verb: 堪える is to endure. Something unendurable, or a gratitude too great to contain.', 'in-review', true, 415),
  ('gp-wo-yogi-nakusareru', 'lang-ja', 'wo-yoginaku-sareru', '〜を余儀なくされる', 'Noun + を余儀なくされる', 'lvl-ja-n1', 'expression', 'formal', 'Be forced into.', '中止を余儀なくされた.', 'Passive by nature: circumstance compels, and no agent is named. News writing uses it constantly.', 'in-review', true, 416),
  ('gp-ni-katakunai', 'lang-ja', 'ni-katakunai', '〜に難くない', 'Noun / Verb stem + に難くない', 'lvl-ja-n1', 'expression', 'formal', 'Not hard to.', '想像に難くない.', 'Almost always with 想像 or 察する. It invites the reader to supply the conclusion themselves.', 'in-review', true, 417),
  ('gp-kiwamarinai', 'lang-ja', 'kiwamarinai', '〜極まりない', 'na-Adj stem + 極まりない', 'lvl-ja-n1', 'auxiliary', 'formal', 'Utterly, in the extreme.', '危険極まりない.', 'Despite the ない it is emphatic, not negative — 極まる means to reach a limit, and 極まりない says the limit is nowhere in sight.', 'in-review', true, 418),
  ('gp-no-itari', 'lang-ja', 'no-itari', '〜の至り', 'Noun + の至り', 'lvl-ja-n1', 'expression', 'formal', 'The height of.', '光栄の至りです.', 'Set phrases of formal speech: 光栄, 感激, 赤面. Not productive — the noun cannot be freely swapped.', 'in-review', true, 419),
  ('gp-no-kiwami', 'lang-ja', 'no-kiwami', '〜の極み', 'Noun + の極み', 'lvl-ja-n1', 'expression', 'formal', 'The very peak of.', '贅沢の極み. 感激の極み.', 'Like の至り but usable of things as well as feelings. Both are literary and both are fixed.', 'in-review', true, 420),
  ('gp-to-aitte', 'lang-ja', 'to-aimatte', '〜と相まって', 'Noun + と相まって', 'lvl-ja-n1', 'expression', 'formal', 'Coupled with.', '好天と相まって、人出が多かった.', 'Two causes reinforcing each other, not merely co-occurring. The effect must exceed either alone.', 'in-review', true, 421),
  ('gp-hazumi', 'lang-ja', 'hazumi-ni', '〜はずみに', 'Verb-た + はずみに', 'lvl-ja-n1', 'conjunction', 'casual', 'On the momentum of, accidentally.', '転んだはずみに、財布を落とした.', 'The second event is unintended and physical. It reports a consequence nobody meant.', 'in-review', true, 422),
  ('gp-kiraiga-aru', 'lang-ja', 'kirai-ga-aru', '〜きらいがある', 'Plain present / Noun の + きらいがある', 'lvl-ja-n1', 'expression', 'formal', 'Has an unfortunate tendency.', '物事を悲観的に考えるきらいがある.', 'Nothing to do with 嫌い. A separate 嫌 meaning "leaning", and always a leaning the writer disapproves of.', 'in-review', true, 423),
  ('gp-tomonai', 'lang-ja', 'ni-tomonatte', '〜に伴って', 'Plain present / Noun + に伴って', 'lvl-ja-n1', 'conjunction', 'formal', 'Accompanying, along with.', '経済成長に伴って、環境問題が深刻化した.', 'The second follows from the first as a companion change. につれて stresses gradualness; に伴って stresses that they travel together.', 'in-review', true, 424),
  ('gp-o-yoso-ni', 'lang-ja', 'wo-yoso-ni', '〜をよそに', 'Noun + をよそに', 'lvl-ja-n1', 'expression', 'formal', 'Ignoring, in disregard of.', '住民の反対をよそに、工事が始まった.', 'Critical. It reports that someone pressed on despite something they should have heeded.', 'in-review', true, 425),
  ('gp-nagara-mo-n1', 'lang-ja', 'to-wa-ie-mono-no', '〜ならでは', 'Noun + ならでは', 'lvl-ja-n1', 'expression', 'formal', 'Only possible for.', 'この店ならではの味.', 'Praise. It says the quality belongs uniquely to that source, which is why advertising is fond of it.', 'in-review', true, 426),
  ('gp-nagara-ni-shite', 'lang-ja', 'inagara-ni-shite', '〜いながらにして', 'Noun + いながらにして', 'lvl-ja-n1', 'expression', 'formal', 'Without leaving where you are.', '家にいながらにして、世界中と話せる.', 'It marvels at reach without movement, which is why it attached itself so readily to the internet.', 'in-review', true, 427),
  ('gp-gotoki', 'lang-ja', 'gotoki', '〜ごとき / 〜ごとく', 'Noun の / Plain form + ごとき', 'lvl-ja-n1', 'auxiliary', 'formal', 'Like, as if.', '氷のごとく冷たい. 私ごときが.', 'The classical ようだ. About oneself it becomes self-deprecation; about others it can be contemptuous.', 'in-review', true, 428),
  ('gp-mademo', 'lang-ja', 'to-ittatte', '〜としたって', 'Plain form + としたって', 'lvl-ja-n1', 'conjunction', 'casual', 'Even supposing.', '急いだとしたって、間に合わない.', 'The colloquial としても. It grants the supposition and then denies that it helps.', 'in-review', true, 429),
  ('gp-nakushite', 'lang-ja', 'nakushite', '〜なくして', 'Noun + なくして', 'lvl-ja-n1', 'expression', 'formal', 'Without, there would be no.', '努力なくして成功はない.', 'Takes a negative second half and states a precondition absolutely. Slogans and mottos live here.', 'in-review', true, 430),
  ('gp-mo-saru-koto-nagara', 'lang-ja', 'mo-sarukoto-nagara', '〜もさることながら', 'Noun + もさることながら', 'lvl-ja-n1', 'conjunction', 'formal', 'That goes without saying, but even more so.', '味もさることながら、値段が魅力だ.', 'It concedes the obvious merit in order to point at a better one. Both halves are positive.', 'in-review', true, 431),
  ('gp-ni-shite-hajimete', 'lang-ja', 'ni-shite', '〜にして', 'Noun + にして', 'lvl-ja-n1', 'particle', 'formal', 'Even at, and only at.', '五十歳にして、初めて気づいた.', 'It marks a threshold reached at last. 〜にしてはじめて makes that explicit.', 'in-review', true, 432),
  ('gp-arawasu', 'lang-ja', 'to-omoikiya', '〜と思いきや', 'Plain form + と思いきや', 'lvl-ja-n1', 'conjunction', 'formal', 'You''d think, but no.', '簡単だと思いきや、大変だった.', 'The classical きや marks a supposition immediately overturned. Almost always a pleasant or comic surprise.', 'in-review', true, 433),
  ('gp-tokoro-wo', 'lang-ja', 'tokoro-wo', '〜ところを', 'Plain form / Noun の + ところを', 'lvl-ja-n1', 'conjunction', 'formal', 'At a time when — apologetically.', 'お忙しいところを、ありがとうございます.', 'It acknowledges the imposition before making it. Set-phrase politeness, and hard to overuse.', 'in-review', true, 434),
  ('gp-ni-arazu', 'lang-ja', 'ni-arazu', '〜にあらず', 'Noun + にあらず', 'lvl-ja-n1', 'expression', 'formal', 'Is not — classically.', '人にあらず.', 'The classical negative copula. Confined to quotations, mottos and deliberate archaism.', 'in-review', true, 435),
  ('gp-ba-koso', 'lang-ja', 'ba-koso', '〜ばこそ', 'Verb-ば + こそ', 'lvl-ja-n1', 'conjunction', 'formal', 'Precisely because.', '君を思えばこそ、厳しく言うのだ.', 'The reason given is the true one, offered against a misreading. It usually defends an act that looked unkind.', 'in-review', true, 436),
  ('gp-de-are', 'lang-ja', 'de-are', '〜であれ', 'Noun + であれ', 'lvl-ja-n1', 'conjunction', 'formal', 'Whatever it may be.', 'どんな理由であれ、遅刻は遅刻だ.', 'Often with a question word, and often doubled: 雨であれ雪であれ. Concessive, and unmoved.', 'in-review', true, 437),
  ('gp-you-ga', 'lang-ja', 'you-ga-you-ga', '〜うが〜まいが', 'Volitional + が + negative volitional + が', 'lvl-ja-n1', 'conjunction', 'formal', 'Whether or not.', '行こうが行くまいが、私には関係ない.', 'まい is the classical negative volitional, alive almost only in this pairing. It dismisses both branches at once.', 'in-review', true, 438),
  ('gp-mai', 'lang-ja', 'mai', '〜まい', 'Plain present + まい', 'lvl-ja-n1', 'auxiliary', 'formal', 'Surely not, or I won''t.', '二度と行くまい. 雨は降るまい.', 'A classical negative volitional doing two jobs: refusal about oneself, conjecture about anything else.', 'in-review', true, 439),
  ('gp-nari-nari', 'lang-ja', 'nari-nari', '〜なり〜なり', 'Plain present / Noun + なり + なり', 'lvl-ja-n1', 'particle', 'formal', 'Either — or, whichever.', '電話なりメールなりで連絡してください.', 'It offers alternatives and leaves the choice open. Unlike たり it is not a sample list but a genuine either-or.', 'in-review', true, 440),
  ('gp-dano', 'lang-ja', 'dano', '〜だの〜だの', 'Noun / Plain form + だの', 'lvl-ja-n1', 'particle', 'casual', 'This and that — with irritation.', '暑いだの寒いだの、文句ばかり.', 'A complaining list. やら is exasperated; だの is closer to mocking what was said.', 'in-review', true, 441),
  ('gp-tsu-tsu', 'lang-ja', 'tsu-tsu', '〜つ〜つ', 'Verb stem + つ + Verb stem + つ', 'lvl-ja-n1', 'expression', 'formal', 'Alternately, back and forth.', '行きつ戻りつ. 抜きつ抜かれつ.', 'A classical pairing frozen into a handful of idioms. Not productive — the pairs must be learned whole.', 'in-review', true, 442),
  ('gp-koto-nakare', 'lang-ja', 'koto-naku', '〜ことなく', 'Plain present + ことなく', 'lvl-ja-n1', 'conjunction', 'formal', 'Without ever.', '一度も休むことなく働いた.', 'The written 〜ないで, and it stresses that the thing never once happened over the whole span.', 'in-review', true, 443),
  ('gp-ni-oite', 'lang-ja', 'ni-oite', '〜において', 'Noun + において', 'lvl-ja-n1', 'particle', 'formal', 'In, at — formally.', '会議は本社において行われます.', 'The written で for place, time and field. における before a noun: 現代における課題.', 'in-review', true, 444),
  ('gp-wo-tsuujite', 'lang-ja', 'wo-tsuujite', '〜を通じて', 'Noun + を通じて', 'lvl-ja-n1', 'particle', 'formal', 'Through, throughout.', '友人を通じて知り合った. 一年を通じて.', 'Both a medium and a span. を通して is near-identical; を通じて leans passive, を通して leans deliberate.', 'in-review', true, 445),
  ('gp-yue-ni', 'lang-ja', 'yue-ni', '〜ゆえに', 'Plain form / Noun の + ゆえに', 'lvl-ja-n1', 'conjunction', 'formal', 'Therefore, owing to.', '若さゆえの過ち.', 'Classical and severe. Philosophy, judgements and translations of formal argument are where it survives.', 'in-review', true, 446),
  ('gp-tote', 'lang-ja', 'tote', '〜とて', 'Noun / Plain form + とて', 'lvl-ja-n1', 'conjunction', 'formal', 'Even, even though.', '私とて人間だ.', 'A classical concessive, now rare outside literary writing. It admits the speaker to the same category as everyone else.', 'in-review', true, 447),
  ('gp-hoka-nai', 'lang-ja', 'yori-hoka-nai', '〜よりほかない', 'Plain present + よりほかない', 'lvl-ja-n1', 'expression', 'formal', 'There is nothing for it but.', '待つよりほかない.', 'Resignation. しかない says the same thing more plainly; よりほかない is the written, weightier form.', 'in-review', true, 448),
  ('gp-douni-mo', 'lang-ja', 'dou-ni-mo', '〜どうにも〜ない', 'どうにも + potential-ない', 'lvl-ja-n1', 'expression', 'casual', 'No matter what, cannot.', 'どうにも我慢できない.', 'Every avenue exhausted, not merely one. It is the difference between "I can''t" and "there is no way".', 'in-review', true, 449),
  ('gp-ni-shiro', 'lang-ja', 'ni-shiro', '〜にしろ〜にしろ', 'Noun / Plain form + にしろ', 'lvl-ja-n1', 'conjunction', 'formal', 'Whether — or.', '行くにしろ行かないにしろ、連絡はしてほしい.', 'にせよ is the same pattern in a slightly more formal key. Both dismiss the choice as irrelevant to what follows.', 'in-review', true, 450),
  ('gp-hitotsu', 'lang-ja', 'hitotsu-de', '〜ひとつで', 'Noun + ひとつで', 'lvl-ja-n1', 'expression', 'formal', 'On this alone it turns.', '考え方ひとつで、人生が変わる.', 'It isolates one small factor as decisive, and the effect named is usually out of proportion to it.', 'in-review', true, 451),
  ('gp-ga-yue-ni', 'lang-ja', 'ga-yue-ni', '〜がゆえに', 'Plain form + がゆえに', 'lvl-ja-n1', 'conjunction', 'formal', 'Precisely because.', '真剣であるがゆえに、衝突する.', 'The が is a classical genitive, not the modern subject marker — which is why it can sit where modern grammar would not allow it.', 'in-review', true, 452),
  ('gp-shimatsu-da', 'lang-ja', 'shimatsu-da', '〜始末だ', 'Plain present + 始末だ', 'lvl-ja-n1', 'expression', 'formal', 'It ended up at this sorry pass.', '最後には泣き出す始末だ.', 'The end of a downward run, and always deplorable. It reports the final indignity in a list of them.', 'in-review', true, 453),
  ('gp-tote-mo', 'lang-ja', 'ta-tokoro-de', '〜たところで', 'Verb-た + ところで', 'lvl-ja-n1', 'conjunction', 'formal', 'Even if you did, it wouldn''t help.', '今さら謝ったところで、遅い.', 'The second half must be negative or futile. It supposes an action and denies it any effect.', 'in-review', true, 454)
